CREATE TABLE IF NOT EXISTS auth_nonces (nonce TEXT PRIMARY KEY, address TEXT NOT NULL, message TEXT NOT NULL, expires_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_auth_nonces_expiry ON auth_nonces(expires_at);
CREATE TABLE IF NOT EXISTS usage (address TEXT NOT NULL, day TEXT NOT NULL, requests INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(address, day));
CREATE TABLE IF NOT EXISTS chat_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, address TEXT NOT NULL, created_at INTEGER NOT NULL, model TEXT, input_chars INTEGER NOT NULL DEFAULT 0);